Об'єкт Що це Скільки <code>Bot</code> клієнт Bot API: токен, HTTP-сесія, типові налаштування (<code>parse_mode</code>) один на токен <code>Dispatcher</code> приймає <code>Update</code>, проганяє через middleware, шукає handler; кореневий <code>Router</code> один на процес (на застосунок) <code>Router</code> група handlers з фільтрами; підключається до диспетчера чи іншого роутера скільки завгодно <p>Handler — функція з фільтрами. aiogram перевіряє handlers згори донизу і викликає перший, чиї фільтри пройшли:</p> telegram_demo.py (фрагмент)<pre><code>def build_router() -&gt; Router:
    """Новий Router на кожен виклик: один Router можна підключити лише до одного Dispatcher."""
    router = Router(name="demo")

    @router.message(CommandStart())
    async def start(message: Message) -&gt; None: ...

    @router.message(Command("subscribe"))
    async def subscribe(message: Message, command: CommandObject, state: FSMContext) -&gt; None: ...

    @router.message(Subscribe.waiting_word, F.text)
    async def got_word(message: Message, state: FSMContext) -&gt; None: ...

    @router.callback_query(Unsubscribe.filter())
    async def unsubscribe(query: CallbackQuery, callback_data: Unsubscribe) -&gt; None: ...

    @router.message(F.text.startswith("/"))
    async def unknown_command(message: Message) -&gt; None: ...      # останнім: «будь-яка команда»

    return router
</code></pre> <ul> <li>Фільтри — <code>CommandStart()</code>, <code>Command("subscribe")</code>, стан FSM, «магічний» <code>F</code> (<code>F.text</code>, <code>F.text.startswith("/")</code>, <code>F.chat.type == "private"</code>).</li> <li>Параметри handler — не з позиції, а за назвою: <code>message</code>, <code>command</code> (аргументи команди), <code>state</code> (FSM), <code>callback_data</code> (розібраний <code>CallbackData</code>) і все, що middleware поклало в <code>data</code>. Те саме, що <code>Depends</code> у FastAPI, але за іменем.</li> <li>«Будь-що» — останнім. Handler <code>F.text</code> перед <code>Command(...)</code> перехопить і команди.</li> </ul>

Підхід до розв'язку <p><code>news_hub/models.py</code> — одна зміна:</p> <pre><code>ALLOWED_DOMAINS: tuple[str, ...] = ("rbc.ua", "pravda.com.ua", "epravda.com.ua", "ukrinform.ua")
</code></pre> <p><code>news_hub/atom.py</code>:</p> <pre><code>import xml.etree.ElementTree as ET
from datetime import datetime, timezone
from urllib.parse import urljoin
from zoneinfo import ZoneInfo

from bs4 import BeautifulSoup

from .parser import RawNews

ATOM = "{http://www.w3.org/2005/Atom}"
XML_BASE = "{http://www.w3.org/XML/1998/namespace}base"
KYIV = ZoneInfo("Europe/Kyiv")


def _text(entry: ET.Element, tag: str) -&gt; str:
    found = entry.find(ATOM + tag)
    return (found.text or "").strip() if found is not None else ""


def _alternate_href(entry: ET.Element) -&gt; str:
    for link in entry.findall(ATOM + "link"):
        if link.get("rel", "alternate") == "alternate" and link.get("href"):
            return link.get("href", "").strip()
    return ""


def _kyiv_datetime(value: str) -&gt; str:
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        return ""
    if parsed.tzinfo is None:
        parsed = parsed.replace(tzinfo=timezone.utc)
    return parsed.astimezone(KYIV).replace(tzinfo=None).isoformat()


def parse_atom(feed: str, feed_url: str) -&gt; list[RawNews]:
    try:
        root = ET.fromstring(feed)
    except ET.ParseError as error:
        raise ValueError(f"пошкоджений Atom: {error}") from error
    if root.tag != ATOM + "feed":
        raise ValueError(f"очікуємо Atom (&lt;feed&gt;), а отримали &lt;{root.tag}&gt;")

    base = urljoin(feed_url, root.get(XML_BASE, ""))
    news_list: list[RawNews] = []
    seen_urls: set[str] = set()
    for entry in root.iter(ATOM + "entry"):
        href = _alternate_href(entry)
        url = urljoin(base, href) if href else ""
        if not url or url in seen_urls:
            continue
        seen_urls.add(url)
        category = entry.find(ATOM + "category")
        news_list.append({
            "title": _text(entry, "title"),
            "url": url,
            "category": (category.get("term", "") if category is not None else "").strip(),
            "description": BeautifulSoup(_text(entry, "summary"), "html.parser").get_text().strip(),
            "datetime": _kyiv_datetime(_text(entry, "published") or _text(entry, "updated")),
        })
    return news_list
</code></pre> <p><code>news_hub/feeds.py</code> використовує <code>HEADERS</code>, <code>PageResult</code>, <code>ScrapeOutcome</code> і <code>_outcome</code> зі <code>scraper.py</code>. Нової моделі результату немає:</p> <pre><code>def parse_feed(text: str, feed_url: str) -&gt; list[RawNews]:
    try:
        root = ET.fromstring(text)
    except ET.ParseError as error:
        raise ValueError(f"пошкоджена стрічка: {error}") from error
    if root.tag == "rss":
        return parse_pravda_rss(text)
    if root.tag == ATOM + "feed":
        return parse_atom(text, feed_url)
    raise ValueError(f"невідомий формат стрічки: &lt;{root.tag}&gt;")


async def fetch_feed(session: aiohttp.ClientSession, url: str, t0: float) -&gt; tuple[PageResult, list[RawNews]]:
    start = time.perf_counter() - t0
    error = None
    items: list[RawNews] = []
    try:
        async with session.get(url, headers=HEADERS, timeout=aiohttp.ClientTimeout(total=15)) as resp:
            resp.raise_for_status()
            text = await resp.text(errors="replace")
        items = parse_feed(text, url)
    except (aiohttp.ClientError, asyncio.TimeoutError, ValueError) as e:
        error = f"{type(e).__name__}: {e}"
    end = time.perf_counter() - t0
    return PageResult(url=url, start=round(start, 3), end=round(end, 3), count=len(items), error=error), items


async def scrape_feeds(feeds: list[str]) -&gt; ScrapeOutcome:
    t0 = time.perf_counter()
    async with aiohttp.ClientSession() as session:
        results = await asyncio.gather(*(fetch_feed(session, url, t0) for url in feeds))
    return _outcome(list(results), t0)
